package ml.inference.server

import java.nio.{ByteBuffer, ByteOrder}
import java.net.InetSocketAddress
import java.nio.channels.{ServerSocketChannel, SocketChannel}
import java.util.concurrent.{ConcurrentHashMap, Executors}
import scala.collection.mutable.ArrayBuffer

object InferenceServer {
  val MODEL_INPUT_DIM = 512
  val MAX_BATCH_SIZE = 32
  val HEADER_SIZE = 16
  val POOL_SIZE = Runtime.getRuntime.availableProcessors()

  // Pre-allocated native buffer pool for zero-copy inference
  // Each buffer sized for max batch of float32 vectors
  private val bufferPool = new ConcurrentHashMap[Long, ByteBuffer]()
  private val executor = Executors.newFixedThreadPool(POOL_SIZE)

  case class InferenceRequest(
    clientId: Long,
    batchSize: Int,
    sequenceLength: Int,
    payload: ByteBuffer
  )

  case class TensorShape(dims: Array[Int]) {
    def totalElements: Int = dims.foldLeft(1)(_ * _)
    def byteSize: Int = totalElements * 4 // float32
  }

  class ModelExecutor(modelPath: String) {
    private val weights: Array[Float] = loadWeights(modelPath)

    private def loadWeights(path: String): Array[Float] = {
      // Simulated weight loading from persistent volume
      Array.fill(MODEL_INPUT_DIM * MODEL_INPUT_DIM)(0.01f)
    }

    def infer(input: ByteBuffer, shape: TensorShape): Array[Float] = {
      val output = new Array[Float](shape.dims(0) * MODEL_INPUT_DIM)
      val inputFloats = new Array[Float](shape.totalElements)
      input.asFloatBuffer().get(inputFloats)

      // Matrix multiply: input[batch, seq] x weights[seq, hidden]
      for (b <- 0 until shape.dims(0)) {
        for (h <- 0 until MODEL_INPUT_DIM) {
          var sum = 0.0f
          for (s <- 0 until shape.dims(1)) {
            sum += inputFloats(b * shape.dims(1) + s) * weights(s * MODEL_INPUT_DIM + h)
          }
          output(b * MODEL_INPUT_DIM + h) = sum
        }
      }
      output
    }
  }

  class RequestHandler(modelExecutor: ModelExecutor) {

    def parseHeader(buffer: ByteBuffer): InferenceRequest = {
      buffer.order(ByteOrder.LITTLE_ENDIAN)
      val clientId = buffer.getLong()
      val batchSize = buffer.getShort() & 0xFFFF  // unsigned short
      val sequenceLength = buffer.getShort() & 0xFFFF
      val flags = buffer.getInt()

      InferenceRequest(clientId, batchSize, sequenceLength, buffer)
    }

    def computeBufferSize(request: InferenceRequest): Long = {
      // Calculate required buffer size for the tensor data
      // Use Long arithmetic to prevent overflow of two unsigned shorts
      val elemCount: Long = request.batchSize.toLong * request.sequenceLength.toLong
      val byteSize: Long = elemCount * 4L  // 4 bytes per float32
      byteSize
    }

    def handleRequest(channel: SocketChannel): Unit = {
      val headerBuf = ByteBuffer.allocate(HEADER_SIZE)
      readFully(channel, headerBuf)
      headerBuf.flip()

      val request = parseHeader(headerBuf)
      val requiredSize = computeBufferSize(request)

      // Validate against our maximum allocation
      // MAX_BATCH_SIZE * MODEL_INPUT_DIM * 4 = 32 * 512 * 4 = 65536
      if (requiredSize <= 0L || requiredSize > MAX_BATCH_SIZE.toLong * MODEL_INPUT_DIM.toLong * 4L) {
        sendError(channel, "Request exceeds maximum tensor size")
        return
      }

      // Validate each dimension independently to prevent out-of-bounds
      // indexing into the fixed-size weights array (weights is
      // MODEL_INPUT_DIM x MODEL_INPUT_DIM) and oversized output allocation.
      if (request.batchSize <= 0 || request.batchSize > MAX_BATCH_SIZE) {
        sendError(channel, "Invalid batch size")
        return
      }
      if (request.sequenceLength <= 0 || request.sequenceLength > MODEL_INPUT_DIM) {
        sendError(channel, "Invalid sequence length")
        return
      }

      // Allocate buffer based on computed size (safe to cast, validated above)
      val tensorBuffer = ByteBuffer.allocateDirect(requiredSize.toInt)
      tensorBuffer.order(ByteOrder.LITTLE_ENDIAN)
      readFully(channel, tensorBuffer)
      tensorBuffer.flip()

      val shape = TensorShape(Array(request.batchSize, request.sequenceLength))
      val result = modelExecutor.infer(tensorBuffer, shape)

      sendResponse(channel, result)
    }

    private def readFully(channel: SocketChannel, buffer: ByteBuffer): Unit = {
      while (buffer.hasRemaining) {
        if (channel.read(buffer) == -1) {
          throw new RuntimeException("Connection closed prematurely")
        }
      }
    }

    private def sendError(channel: SocketChannel, msg: String): Unit = {
      val bytes = msg.getBytes("UTF-8")
      val resp = ByteBuffer.allocate(4 + bytes.length)
      resp.putInt(-1)
      resp.put(bytes)
      resp.flip()
      channel.write(resp)
    }

    private def sendResponse(channel: SocketChannel, data: Array[Float]): Unit = {
      val resp = ByteBuffer.allocate(4 + data.length * 4)
      resp.order(ByteOrder.LITTLE_ENDIAN)
      resp.putInt(data.length)
      resp.asFloatBuffer().put(data)
      resp.position(4 + data.length * 4)
      resp.flip()
      channel.write(resp)
    }
  }

  def main(args: Array[String]): Unit = {
    val port = sys.env.getOrElse("INFERENCE_PORT", "8090").toInt
    val modelPath = sys.env.getOrElse("MODEL_PATH", "/models/default")

    val serverChannel = ServerSocketChannel.open()
    serverChannel.bind(new InetSocketAddress("0.0.0.0", port))

    val modelExecutor = new ModelExecutor(modelPath)
    val handler = new RequestHandler(modelExecutor)

    println(s"Inference server listening on port $port")

    while (true) {
      val clientChannel = serverChannel.accept()
      executor.submit(new Runnable {
        def run(): Unit = {
          try {
            handler.handleRequest(clientChannel)
          } catch {
            case e: Exception =>
              println(s"Error handling request: ${e.getMessage}")
          } finally {
            clientChannel.close()
          }
        }
      })
    }
  }
}
